package io.github.jackotom.hongguo.android;

import java.io.*;
import java.net.*;
import java.lang.reflect.*;
import java.nio.file.Files;
import java.util.*;
import java.util.function.Consumer;
import org.json.*;

/** Actual source/quality/cache classes and real URL validator; only transport/bridge/crypto are doubles. */
public final class MediaRedirectRecoveryTest {
    static final String SID="981001",VID="981032",QUERY="?fixture_token=a%2Fb+c%2Bd%26e&path=%2Fseg%2Bmp4&empty=";
    static final List<JSONArray> lookups=new ArrayList<>();
    static final List<String> stages=new ArrayList<>();
    static final Map<String,JSONObject> fresh=new HashMap<>();
    static final Map<String,JSONObject> models=new HashMap<>();
    static int passed,failed,checks;static File directory;static MainActivity host;
    interface Checked {void run()throws Exception;}
    static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    static Exception reject(Checked body,String label)throws Exception{try{body.run();}catch(Exception expected){checks++;return expected;}throw new AssertionError(label);}
    static void group(String label,Checked body){try{reset();body.run();passed++;System.out.println("PASS "+label);}catch(Throwable error){failed++;System.out.println("FAIL "+label+": "+error.getClass().getSimpleName()+" "+error.getMessage());}finally{Thread.interrupted();}}
    @SuppressWarnings("unchecked") static void reset()throws Exception{
        RedirectTransferFixture.reset();CencDecryptor.keys.clear();CencDecryptor.calls.clear();lookups.clear();stages.clear();fresh.clear();models.clear();
        for(String name:new String[]{"plans","failedWebUntil"}){Field field=PlaybackSources.class.getDeclaredField(name);field.setAccessible(true);Map<Object,Object> map=(Map<Object,Object>)field.get(null);synchronized(map){map.clear();}}
        host.callback=script->{try{JSONArray args=new JSONArray("["+script.substring(script.lastIndexOf('(')+1,script.length()-1)+"]");lookups.add(args);JSONObject info=fresh.get(args.getString(3));if(info==null)throw new AssertionError("unexpected lookup quality "+args.getString(3));PlaybackSources.result(new JSONObject().put("requestId",args.getString(0)).put("seriesId",args.getString(1)).put("vid",args.getString(2)).put("requestedQuality",args.getString(3)).put("playInfo",info));}catch(Exception error){throw new RuntimeException(error);}};
    }
    static JSONObject model(String name,String quality,int n)throws Exception{
        String url="https://cdn.qznovelvod.com/redirect-fixture-"+name+".mp4"+QUERY,key=String.format(Locale.ROOT,"%032x",n+1);
        JSONObject row=new JSONObject().put("url",url).put("seriesId",SID).put("vid",VID).put("source","app").put("requestedQuality",quality).put("width",quality.equals("1080p")?1920:1280).put("height",quality.equals("1080p")?1080:720).put("contentKey",key).put("userAgent","fixture-agent-"+n).put("referer","https://novelquickapp.com/");
        CencDecryptor.keys.put(url,bytes(key));models.put(url,row);return row;
    }
    static byte[] bytes(String hex){byte[] out=new byte[16];for(int i=0;i<16;i++)out[i]=(byte)Integer.parseInt(hex.substring(i*2,i*2+2),16);return out;}
    static JSONObject candidates(String name,String quality,int count,int base)throws Exception{JSONObject row=model(name+"-0",quality,base);JSONArray list=new JSONArray();for(int i=1;i<count;i++)list.put(model(name+"-"+i,quality,base+i));row.put("variants",list);return row;}
    static List<String> urls(JSONObject row)throws Exception{List<String> list=new ArrayList<>();list.add(row.getString("url"));JSONArray variants=row.optJSONArray("variants");if(variants!=null)for(int i=0;i<variants.length();i++)list.add(variants.getJSONObject(i).getString("url"));return list;}
    static void failing(JSONObject row,String outcome)throws Exception{for(String url:urls(row))RedirectTransferFixture.outcomes.put(url,outcome);}
    static void noSecrets(Throwable error){Set<Throwable> seen=Collections.newSetFromMap(new IdentityHashMap<Throwable,Boolean>());for(Throwable value=error;value!=null&&seen.add(value);value=value.getCause()){String msg=String.valueOf(value.getMessage());check(!msg.contains("fixture_token")&&!msg.contains("redirect-fixture")&&!msg.contains("https://")&&!msg.contains("http://"),"diagnostic must omit URL and signature");}}
    static void assertions()throws Exception{
        for(RedirectTransferFixture.Transfer value:RedirectTransferFixture.transfers){JSONObject row=models.get(value.url);check(value.clean,"every candidate starts without stale .part bytes");if(row!=null){check(value.url.endsWith(QUERY),"signed query is passed without normalization");check(value.ua.equals(row.getString("userAgent"))&&value.ref.equals(row.getString("referer")),"candidate owns its own exact UA/referer");}}
        for(JSONArray args:lookups)check(args.getString(1).equals(SID)&&args.getString(2).equals(VID),"refresh keeps series and episode identity");
        check(EpisodeResolver.calls==0,"no unrelated web lookup");
    }
    static File part(String name){return new File(directory,name+".part");}
    static void completed(File target)throws Exception{check(Arrays.equals(Files.readAllBytes(target.toPath()),new byte[]{7,8,9}),"published bytes belong to successfully decrypted candidate");}
    static void cleanup(File file){if(file.isDirectory()){File[] files=file.listFiles();if(files!=null)for(File child:files)cleanup(child);}file.delete();}
    static final class Flow {
        final Map<String,JSONObject> old=new HashMap<>();final File cacheDir;final PlaybackCachePolicy cache;String active;
        Flow(String name){cacheDir=new File(directory,name);cache=new PlaybackCachePolicy(cacheDir,256,64,(url,target,max)->PlaybackSources.download(url,target,max,active));}
        AdaptiveQuality.Result<File> run(String quality)throws Exception{return AdaptiveQuality.prepare(quality,q->{active=q;JSONObject row=old.get(q);if(row==null)throw new AssertionError("unexpected stage "+q);PlaybackSources.Plan plan=PlaybackSources.register(row,VID,false);return cache.fetch(SID,MediaQuality.cacheVid(VID,q),32,plan.url);},PlaybackSources::canLowerQuality,()->true,(q,n,error)->stages.add(q),file->{});}
    }
    static void initialFatal(String name,java.util.function.UnaryOperator<JSONObject> change)throws Exception{
        Flow flow=new Flow("bad-metadata-"+name);flow.old.put("1080p",change.apply(model(name,"1080p",0)));Exception error=reject(()->flow.run("1080p"),"invalid metadata accepted");check(!PlaybackSources.canLowerQuality(error),"initial metadata does not turn into transient redirect");check(stages.equals(Collections.singletonList("1080p"))&&RedirectTransferFixture.transfers.isEmpty()&&lookups.isEmpty(),"invalid metadata stops before all media or lower quality work");
    }
    public static void main(String[]args)throws Exception{
        directory=Files.createTempDirectory("hongguo-media-redirect-recovery-").toFile();host=new MainActivity();PlaybackSources.attach(host);
        try{
            group("absolute signed HTTPS redirect stays byte exact",()->{String location="https://edge.fqnovelvod.com/video.mp4"+QUERY;URI to=RedirectTransferFixture.redirect(new URI("https://cdn.qznovelvod.com/start.mp4"),location);check(to.toString().equals(location),"absolute signed URI preserved");});
            group("relative and protocol-relative HTTPS redirects retain raw escaping",()->{URI from=new URI("https://cdn.qznovelvod.com/path/start.mp4");for(String location:new String[]{"next.mp4"+QUERY,"/new.mp4"+QUERY,"//edge.fqnovelvod.com/clip.mp4"+QUERY}){URI to=RedirectTransferFixture.redirect(from,location);check(to.toString().equals(from.resolve(location).toString())&&to.getRawQuery().equals(QUERY.substring(1)),"relative redirect resolved without decode/re-encode");}});
            final String[] rejected={null,""," ","http://edge.fqnovelvod.com/v.mp4?fixture_token=private","https://user:pass@edge.fqnovelvod.com/v.mp4","https://edge.fqnovelvod.com/v.mp4#frag","https://edge.fqnovelvod.com:8443/v.mp4","https://127.0.0.1/v.mp4","https://receiver.local/v.mp4","https://receiver.internal/v.mp4","https://receiver.lan/v.mp4","https://receiver.home/v.mp4","https://localhost/v.mp4","https://edge.fqnovelvod.com/%broken","https://edge.fqnovelvod.com/v.mp4\r\nX: secret", "https://edge.fqnovelvod.com/"+String.join("",Collections.nCopies(4100,"x"))};
            for(int i=0;i<rejected.length;i++){final int n=i;group("invalid media Location "+i+" becomes sanitized typed recovery, never follows",()->{Exception error=reject(()->RedirectTransferFixture.redirect(new URI("https://cdn.qznovelvod.com/start.mp4"),rejected[n]),"invalid Location accepted");check(error.getClass().getSimpleName().equals("MediaRedirectException"),"only media redirect rejection gets typed classification");check(error.getCause()==null,"invalid Location syntax/cause cannot leak or veto recovery");check(PlaybackSources.canLowerQuality(error),"typed redirect qualifies after source exhaustion");check(!PlaybackSources.canLowerQuality(new IOException(error.getMessage())),"identical generic message is not enough");noSecrets(error);check(RedirectTransferFixture.followed.isEmpty(),"invalid Location has zero downstream request");});}
            group("actual media 3xx branch handles missing Location and caps redirect loops",()->{
                URI from=new URI("https://cdn.qznovelvod.com/start.mp4");Map<String,String> headers=new HashMap<>();
                for(int count:new int[]{0,1,2}){final int n=count;Exception error=reject(()->NetworkGuard.fixtureRedirectResponse(n,from,headers),"missing Location accepted");check(error.getClass().getSimpleName().equals("MediaRedirectException")&&PlaybackSources.canLowerQuality(error)&&error.getCause()==null,"missing header is media-only typed without URL cause");noSecrets(error);}
                headers.put("location","https://edge.fqnovelvod.com/video.mp4"+QUERY);
                for(int count:new int[]{0,1,2})check(NetworkGuard.fixtureRedirectResponse(count,from,headers).toString().equals(headers.get("location")),"up to three valid redirected targets preserve signed URL");
                Exception loop=reject(()->NetworkGuard.fixtureRedirectResponse(3,from,headers),"fourth redirect accepted");check(loop.getClass().getSimpleName().equals("MediaRedirectException")&&PlaybackSources.canLowerQuality(loop)&&loop.getCause()==null,"fourth response redirect stops before another target");noSecrets(loop);
            });
            group("same-quality alternate succeeds before refresh",()->{JSONObject old=candidates("alternate","1080p",3,0);failing(old,"redirect");String alternate=urls(old).get(1);RedirectTransferFixture.outcomes.put(alternate,"ok");PlaybackSources.register(old,VID,false);File target=part("alternate");PlaybackSources.download(old.getString("url"),target,64,"1080p");check(RedirectTransferFixture.urls().equals(urls(old).subList(0,2))&&lookups.isEmpty(),"primary rejection then first alternate only");check(CencDecryptor.calls.equals(Collections.singletonList(alternate)),"only successful alternate decrypts with its own key");completed(target);assertions();});
            group("same-quality fresh model recovers media redirect",()->{JSONObject old=candidates("fresh-old","1080p",2,10),renewed=model("fresh-new","1080p",20);failing(old,"redirect");fresh.put("1080p",renewed);PlaybackSources.Plan identity=PlaybackSources.register(old,VID,false);File target=part("fresh");PlaybackSources.download(old.getString("url"),target,64,"1080p");List<String> expected=urls(old);expected.add(renewed.getString("url"));check(RedirectTransferFixture.urls().equals(expected)&&lookups.size()==1,"exhaust same-quality candidates before exactly one renewed model");check(lookups.get(0).getString(3).equals("1080p"),"renewed model retains selected quality");check(PlaybackSources.find(old.getString("url"),"1080p")==identity&&PlaybackSources.find(renewed.getString("url"),"1080p")==null,"fresh plan remains job-local and original cache identity remains");completed(target);assertions();});
            group("1080p exhaustion automatically uses 720p cache identity",()->{Flow flow=new Flow("quality720");JSONObject a=model("high-old","1080p",1),b=model("high-fresh","1080p",2),c=model("low-old","720p",3);flow.old.put("1080p",a);flow.old.put("720p",c);fresh.put("1080p",b);failing(a,"redirect");failing(b,"redirect");AdaptiveQuality.Result<File> result=flow.run("1080p");check(stages.equals(Arrays.asList("1080p","720p"))&&result.quality.equals("720p")&&result.stages==2,"bounded adaptive coordinator reports actual 720p stage");check(flow.cache.find(SID,MediaQuality.cacheVid(VID,"1080p"),32)==null&&result.value.equals(flow.cache.find(SID,MediaQuality.cacheVid(VID,"720p"),32)),"low quality never aliases preferred high-quality cache");completed(result.value);assertions();});
            group("1080p then 720p then auto succeeds with exact quality cache identity",()->{Flow flow=new Flow("quality-auto");for(String q:new String[]{"1080p","720p","auto"}){JSONObject a=model("auto-old-"+q,q,1),b=model("auto-fresh-"+q,q,2);flow.old.put(q,a);fresh.put(q,b);if(!q.equals("auto")){failing(a,"redirect");failing(b,"redirect");}}AdaptiveQuality.Result<File> result=flow.run("1080p");check(stages.equals(Arrays.asList("1080p","720p","auto"))&&result.quality.equals("auto")&&result.stages==3,"third stage is auto, not a loop");check(result.value.equals(flow.cache.find(SID,MediaQuality.cacheVid(VID,"auto"),32))&&flow.cache.find(SID,VID,32)==null&&flow.cache.find(SID,MediaQuality.cacheVid(VID,"1080p"),32)==null&&flow.cache.find(SID,MediaQuality.cacheVid(VID,"720p"),32)==null,"auto-only full-source cache contains successful data, legacy excluded");check(lookups.size()==2,"one fresh per failed quality before lower stage");completed(result.value);assertions();});
            group("720p starts at 720p then auto without trying 1080p",()->{Flow flow=new Flow("start720");JSONObject a=model("start720-old","720p",1),b=model("start720-fresh","720p",2);flow.old.put("720p",a);fresh.put("720p",b);flow.old.put("auto",model("start720-auto","auto",3));failing(a,"redirect");failing(b,"redirect");AdaptiveQuality.Result<File> result=flow.run("720p");check(stages.equals(Arrays.asList("720p","auto"))&&result.quality.equals("auto"),"only lower stages are visited");assertions();});
            group("all redirect failures stop at 16 transfers per quality and 3 stages with no cache part",()->{Flow flow=new Flow("all-failed");for(String q:new String[]{"1080p","720p","auto"}){JSONObject a=candidates("bound-old-"+q,q,8,0),b=candidates("bound-fresh-"+q,q,8,20);flow.old.put(q,a);fresh.put(q,b);failing(a,"redirect");failing(b,"redirect");}Exception error=reject(()->flow.run("1080p"),"all failure cache published");check(stages.equals(Arrays.asList("1080p","720p","auto"))&&RedirectTransferFixture.transfers.size()==48&&lookups.size()==3,"global loop bounded at 3 times 16, one refresh per quality");check(flow.cache.status().files==0&&flow.cacheDir.listFiles().length==0,"failed transfers leave no .part and no playable cache");check(CencDecryptor.calls.isEmpty()&&RedirectTransferFixture.followed.isEmpty(),"no rejected Location produces downstream transfer or decrypt");noSecrets(error);assertions();});
            group("cancel TLS and same-text generic failures never lower or refresh",()->{for(String mode:new String[]{"cancel","tls","tls-redirect","generic","generic-old-text"}){reset();Flow flow=new Flow("fatal-"+mode);JSONObject a=model("fatal-"+mode,"1080p",1);flow.old.put("1080p",a);failing(a,mode);Exception error=reject(()->flow.run("1080p"),"fatal failure accepted");check(stages.equals(Collections.singletonList("1080p"))&&lookups.isEmpty()&&RedirectTransferFixture.transfers.size()==1,"fatal/cancel keeps quality and never repeats source");check(flow.cache.status().files==0&&flow.cacheDir.listFiles().length==0&&!PlaybackSources.canLowerQuality(error),"fatal/cancel cleans part and denies fallback");Thread.interrupted();}});
            group("cancellation during fresh retry delay interrupts before refresh or lower quality",()->{Flow flow=new Flow("cancel-delay");JSONObject a=model("delay-old","1080p",1);flow.old.put("1080p",a);failing(a,"redirect");java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();Thread worker=new Thread(()->{try{flow.run("1080p");}catch(Throwable error){failure.set(error);}});worker.start();long deadline=System.nanoTime()+1_000_000_000L;while(worker.isAlive()&&worker.getState()!=Thread.State.TIMED_WAITING&&System.nanoTime()<deadline)Thread.sleep(1);check(worker.isAlive()&&worker.getState()==Thread.State.TIMED_WAITING,"retry delay exists before renew");worker.interrupt();worker.join(1500);check(!worker.isAlive()&&failure.get()!=null&&lookups.isEmpty()&&stages.equals(Collections.singletonList("1080p")),"cancel ends work before lookup and quality transition");check(flow.cacheDir.listFiles().length==0,"cancelled delay leaves no partial bytes");});
            group("legal initial HTTPS with bad redirect never opens rejected downstream",()->{JSONObject a=model("no-follow","1080p",1);failing(a,"redirect");fresh.put("1080p",a);PlaybackSources.register(a,VID,false);Exception error=reject(()->PlaybackSources.download(a.getString("url"),part("no-follow"),64,"1080p"),"invalid downstream accepted");check(RedirectTransferFixture.followed.isEmpty()&&!part("no-follow").exists(),"validation is before downstream transport and part removed");noSecrets(error);});
            group("malformed initial URL is still input failure not typed redirect",()->{JSONObject row=model("initial-http","1080p",1).put("url","http://cdn.qznovelvod.com/a.mp4");Exception error=reject(()->PlaybackSources.register(row,VID,false),"http metadata accepted");check(!error.getClass().getSimpleName().equals("MediaRedirectException")&&!PlaybackSources.canLowerQuality(error),"initial invalid HTTPS stays fatal");check(RedirectTransferFixture.transfers.isEmpty()&&lookups.isEmpty(),"initial URL starts no media attempt");});
            group("identity key headers and variant metadata remain fail-fast",()->{for(String bad:new String[]{"identity","key","headers","host","variant"}){reset();JSONObject row=model("metadata-"+bad,"1080p",1);if(bad.equals("identity"))row.put("vid","999");if(bad.equals("key"))row.put("contentKey","bad");if(bad.equals("headers"))row.put("userAgent","bad\r\nX: input");if(bad.equals("host"))row.put("url","https://unrelated.example/video");if(bad.equals("variant"))row.put("variants",new JSONArray().put(model("bad-variant","1080p",2).put("vid","999")));Flow flow=new Flow("metadata-"+bad);flow.old.put("1080p",row);Exception error=reject(()->flow.run("1080p"),"bad metadata accepted");check(!PlaybackSources.canLowerQuality(error)&&stages.size()==1&&lookups.isEmpty()&&RedirectTransferFixture.transfers.isEmpty(),"invalid whole plan stops before source/quality retry");}});
            System.out.println("MEDIA_REDIRECT_RECOVERY_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" actualUrlValidator=true actualPlaybackSources=true actualAdaptiveQuality=true actualCache=true transport=offline-double networkRequests=0");
            if(failed!=0)throw new AssertionError("media redirect recovery fixture regression failed");
        }finally{PlaybackSources.detach(host);Thread.interrupted();cleanup(directory);}
    }
}
final class MainActivity {Consumer<String> callback;boolean isFinishing(){return false;}boolean isDestroyed(){return false;}void script(String value){callback.accept(value);}}
final class EpisodeResolver {static int calls;static String resolve(String sid,String vid)throws Exception{calls++;throw new IOException("fixture web unavailable");}}
final class AppTransport {static boolean domain(String host,String...allowed){if(host==null)return false;host=host.toLowerCase(Locale.ROOT);for(String suffix:allowed)if(host.equals(suffix)||host.endsWith("."+suffix))return true;return false;}}
final class CencDecryptor {
    static final Map<String,byte[]> keys=new HashMap<>();static final List<String> calls=new ArrayList<>();
    static void decryptInPlace(File target,byte[] key)throws Exception{String url=RedirectTransferFixture.lastUrl;calls.add(url);if(!Arrays.equals(keys.get(url),key))throw new AssertionError("candidate key not matched");Files.write(target.toPath(),new byte[]{7,8,9});}
}
final class RedirectTransferFixture {
    static final String MESSAGE="片源跳转不可用（地址无效或跳转次数超限）";
    static final class Transfer {final String url,ua,ref;final boolean clean;Transfer(String url,String ua,String ref,boolean clean){this.url=url;this.ua=ua;this.ref=ref;this.clean=clean;}}
    static final List<Transfer> transfers=new ArrayList<>();static final List<String> followed=new ArrayList<>();static final Map<String,String> outcomes=new HashMap<>();static String lastUrl;
    static void reset(){transfers.clear();followed.clear();outcomes.clear();lastUrl=null;EpisodeResolver.calls=0;}
    static List<String> urls(){List<String> values=new ArrayList<>();for(Transfer t:transfers)values.add(t.url);return values;}
    static URI redirect(URI from,String location)throws Exception{
        try{Method method=NetworkGuard.class.getDeclaredMethod("mediaRedirect",URI.class,String.class);method.setAccessible(true);try{return(URI)method.invoke(null,from,location);}catch(InvocationTargetException error){Throwable cause=error.getCause();if(cause instanceof Exception)throw(Exception)cause;throw new AssertionError(cause);}}
        catch(NoSuchMethodException original){return NetworkGuard.validate(from.resolve(location).toString(),false);}
    }
    static void download(String url,File target,long max,String ua,String ref)throws Exception{
        URI from=NetworkGuard.validate(url,false);lastUrl=url;transfers.add(new Transfer(url,ua,ref,!target.exists()||target.length()==0));Files.write(target.toPath(),new byte[]{1,2,3,4});
        String mode=outcomes.getOrDefault(url,"ok");
        if(mode.equals("redirect")){URI accepted=redirect(from,"http://edge.fqnovelvod.com/rejected.mp4?fixture_token=must-not-leak");followed.add(accepted.toString());throw new AssertionError("non-HTTPS redirect followed");}
        if(mode.equals("cancel")){Thread.currentThread().interrupt();throw new InterruptedIOException("fixture cancelled");}
        if(mode.equals("generic"))throw new IOException(MESSAGE);
        if(mode.equals("generic-old-text"))throw new IOException("仅接受标准 HTTPS 链接");
        if(mode.startsWith("tls")){javax.net.ssl.SSLHandshakeException tls=new javax.net.ssl.SSLHandshakeException("fixture TLS failure");if(mode.equals("tls-redirect")){try{redirect(from,"http://edge.fqnovelvod.com/a");}catch(Exception error){tls.initCause(error);}}throw tls;}
    }
}
